// entrypoints/broant-rail.content.ts
import { defineContentScript } from 'wxt/utils/define-content-script';
import type { BridgeActivityState } from '@src/store/bridge-activity';

interface RailStateSnapshot {
  visible: boolean;
  opacity?: number;
  topPx?: number;
  sidePanelOpen?: boolean;
  theme: 'dark' | 'light';
  bridgeEnabled: boolean;
  bridgeConnected: boolean;
  pruningMode: 'compact' | 'standard';
  vramLoaded: boolean;
  vramLabel: string;
  activity: BridgeActivityState;
}

const DEFAULT_STATE: RailStateSnapshot = {
  visible: true,
  opacity: 0.85,
  sidePanelOpen: false,
  theme: 'dark',
  bridgeEnabled: false,
  bridgeConnected: false,
  pruningMode: 'compact',
  vramLoaded: false,
  vramLabel: 'LM Studio: idle',
  activity: {
    phase: 'idle',
    activeSessions: 0,
    activeTasks: 0,
    updatedAt: 0,
  },
};

const EMBLEM_SVG = `<svg viewBox="0 0 189 256" width="100%" height="100%" fill="none" aria-hidden="true">
  <image href="data:image/png;base64," width="189" height="256" preserveAspectRatio="xMidYMid meet" />
</svg>`;

const CHIP_SVG = `<svg viewBox="0 0 24 24" width="16" height="16" fill="none" stroke="currentColor" stroke-width="1.8" stroke-linecap="round" stroke-linejoin="round">
  <rect x="6" y="6" width="12" height="12" rx="2"/>
  <rect x="9" y="9" width="6" height="6" rx="0.5"/>
  <path d="M9 2v4M15 2v4M9 18v4M15 18v4M2 9h4M2 15h4M18 9h4M18 15h4"/>
</svg>`;

const BOLT_SVG = `<svg viewBox="0 0 24 24" width="16" height="16" fill="currentColor">
  <path d="M13 2L4.5 13.5h6L9.5 22 19.5 10.5h-6L13 2z"/>
</svg>`;

const GEAR_SVG = `<svg viewBox="0 0 24 24" width="16" height="16" fill="none" stroke="currentColor" stroke-width="1.8" stroke-linecap="round" stroke-linejoin="round">
  <circle cx="12" cy="12" r="3"/>
  <path d="M19.4 15a1.65 1.65 0 0 0 .33 1.82l.06.06a2 2 0 1 1-2.83 2.83l-.06-.06a1.65 1.65 0 0 0-1.82-.33 1.65 1.65 0 0 0-1 1.51V21a2 2 0 1 1-4 0v-.09a1.65 1.65 0 0 0-1-1.51 1.65 1.65 0 0 0-1.82.33l-.06.06a2 2 0 1 1-2.83-2.83l.06-.06a1.65 1.65 0 0 0 .33-1.82 1.65 1.65 0 0 0-1.51-1H3a2 2 0 1 1 0-4h.09a1.65 1.65 0 0 0 1.51-1 1.65 1.65 0 0 0-.33-1.82l-.06-.06a2 2 0 1 1 2.83-2.83l.06.06a1.65 1.65 0 0 0 1.82.33h.08a1.65 1.65 0 0 0 1-1.51V3a2 2 0 1 1 4 0v.09a1.65 1.65 0 0 0 1 1.51 1.65 1.65 0 0 0 1.82-.33l.06-.06a2 2 0 1 1 2.83 2.83l-.06.06a1.65 1.65 0 0 0-.33 1.82v.08a1.65 1.65 0 0 0 1.51 1H21a2 2 0 1 1 0 4h-.09a1.65 1.65 0 0 0-1.51 1z"/>
</svg>`;

const RAIL_CSS = `
:host {
  all: initial;
  position: fixed;
  top: 14px;
  right: 16px;
  z-index: 2147483646;
  font-family: Inter, -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, sans-serif;
  user-select: none;
}
.dock {
  --ba-bg: #14110F;
  --ba-surface: #1E1916;
  --ba-border: #332B26;
  --ba-fg: #F5EFE6;
  --ba-muted: #8C7D72;
  --ba-accent: #C85A32;
  --ba-accent-bright: #E07A5F;
  --ba-honey: #D97706;
  --ba-orbit-alt: #F5EFE6;
  --ba-blue: #3B82F6;
  --ba-danger: #EF4444;
  --ba-shadow: 0 8px 24px rgba(0, 0, 0, 0.45);
  --ba-radius: 12px;

  width: 44px;
  padding: 5px 0;
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: 7px;
  background: var(--ba-bg);
  color: var(--ba-fg);
  border: 1px solid var(--ba-border);
  border-radius: var(--ba-radius);
  box-shadow: var(--ba-shadow);
  opacity: var(--ba-dock-opacity, 0.85);
  backdrop-filter: blur(8px);
  -webkit-backdrop-filter: blur(8px);
  transition: transform 0.18s ease, opacity 0.18s ease;
  cursor: grab;
  touch-action: none;
}
.dock.dragging {
  cursor: grabbing;
  user-select: none;
  transition: none !important;
}
.dock:hover {
  opacity: 1 !important;
}
.dock[data-theme="light"] {
  --ba-bg: #F3ECE1;
  --ba-surface: #E7DCCB;
  --ba-border: #3F2220;
  --ba-fg: #2A1215;
  --ba-muted: #7C655D;
  --ba-accent: #B44324;
  --ba-accent-bright: #C85A32;
  --ba-honey: #D97706;
  --ba-shadow: 0 4px 14px rgba(74, 21, 27, 0.16);
  --ba-radius: 10px;
}
.dock.hidden {
  display: none !important;
}
.dock.tucked {
  position: fixed;
  top: 24px;
  right: 0;
  width: 10px;
  height: 52px;
  padding: 0;
  border-radius: 8px 0 0 8px;
  border-right: none;
  cursor: pointer;
  justify-content: center;
  gap: 4px;
}
.dock.tucked > :not(.tuck-dot) {
  display: none;
}
.tuck-dot {
  display: none;
  width: 5px;
  height: 5px;
  border-radius: 50%;
  background: var(--ba-muted);
}
.dock.tucked .tuck-dot {
  display: block;
}
.btn {
  position: relative;
  width: 32px;
  height: 32px;
  border: none;
  border-radius: 8px;
  background: transparent;
  color: var(--ba-muted);
  cursor: pointer;
  display: flex;
  align-items: center;
  justify-content: center;
  padding: 0;
  transition: background 0.15s ease, color 0.15s ease, transform 0.15s ease;
}
.btn:hover {
  background: var(--ba-surface);
  color: var(--ba-fg);
}
#ba-open {
  width: 42px;
  height: 57px;
  padding: 0;
  margin: 0;
  border: none;
  border-radius: 8px;
  background: transparent;
  display: flex;
  align-items: center;
  justify-content: center;
  overflow: hidden;
  cursor: pointer;
}
#ba-open:hover {
  background: transparent;
  transform: scale(1.05);
}
#ba-open svg {
  width: 100%;
  height: 100%;
  display: block;
}
.divider {
  width: 24px;
  height: 1px;
  background: var(--ba-border);
  margin: 1px 0;
}
/* LED 1: MCP Gate */
.led {
  width: 12px;
  height: 12px;
  border-radius: 50%;
  transition: background 0.2s ease, box-shadow 0.2s ease, transform 0.15s ease;
}
.led-mcp[data-state="on"] {
  background: var(--ba-honey);
  box-shadow: 0 0 8px var(--ba-honey);
}
.led-mcp[data-state="connected"] {
  background: var(--ba-accent-bright);
  box-shadow: 0 0 8px var(--ba-accent-bright);
}
.led-mcp[data-state="off"] {
  background: var(--ba-muted);
  opacity: 0.45;
}
/* LED 2: Agent Activity */
.led-act[data-state="idle"] {
  background: var(--ba-muted);
  opacity: 0.4;
}
.led-act[data-state="thinking"] {
  background: var(--ba-accent);
  box-shadow: 0 0 10px var(--ba-accent);
  animation: ba-breathe 1.2s ease-in-out infinite;
}
.led-act[data-state="executing"] {
  background: var(--ba-accent-bright);
  box-shadow: 0 0 12px var(--ba-honey);
  animation: ba-blink 0.5s ease-in-out infinite;
}
.led-act[data-state="held"] {
  background: var(--ba-blue);
  box-shadow: 0 0 8px var(--ba-blue);
}
.pill {
  font-size: 11px;
  font-weight: 700;
  letter-spacing: -0.5px;
}
.btn-close {
  font-size: 16px;
  line-height: 1;
  color: var(--ba-muted);
}
.btn-close:hover {
  color: #E07A5F;
}
/* Tooltip */
.btn::after {
  content: attr(data-tip);
  position: absolute;
  right: calc(100% + 8px);
  top: 50%;
  transform: translateY(-50%) translateX(4px);
  padding: 4px 8px;
  border-radius: 6px;
  background: var(--ba-bg);
  color: var(--ba-fg);
  border: 1px solid var(--ba-border);
  box-shadow: var(--ba-shadow);
  font-size: 11px;
  font-weight: 500;
  white-space: nowrap;
  pointer-events: none;
  opacity: 0;
  transition: opacity 0.14s ease, transform 0.14s ease;
}
.btn:hover::after,
.btn-act[data-executing="true"]::after {
  opacity: 1;
  transform: translateY(-50%) translateX(0);
}
@keyframes ba-breathe {
  0%, 100% { opacity: 1; transform: scale(1); }
  50% { opacity: 0.45; transform: scale(0.9); }
}
@keyframes ba-blink {
  0% { background: #E07A5F; box-shadow: 0 0 12px #F59E0B; }
  50% { background: #F59E0B; box-shadow: 0 0 4px #C85A32; }
}
`;

export default defineContentScript({
  matches: ['http://*/*', 'https://*/*'],
  runAt: 'document_idle',
  main() {
    if (window.top !== window) return; // do not mount in iframes
    if (document.getElementById('broant-mini-rail-host')) return;

    const host = document.createElement('div');
    host.id = 'broant-mini-rail-host';
    const shadow = host.attachShadow({ mode: 'closed' });
    const style = document.createElement('style');
    style.textContent = RAIL_CSS;

    const dock = document.createElement('div');
    dock.className = 'dock';
    dock.dataset.theme = 'dark';
    dock.innerHTML = `
      <span class="tuck-dot" id="ba-tuck-mcp"></span>
      <span class="tuck-dot" id="ba-tuck-act"></span>
      <button class="btn" id="ba-open" data-tip="BroAnt • Click: Panel | DblClick: Tuck">
        ${EMBLEM_SVG}
      </button>
      <button class="btn" id="ba-mcp" data-tip="MCP Gate: OFF">
        <span class="led led-mcp" data-state="off"></span>
      </button>
      <button class="btn btn-act" id="ba-act" data-active="false" data-executing="false" data-tip="Agent: Idle">
        <span class="led led-act" data-state="idle"></span>
      </button>
      <div class="divider"></div>
      <button class="btn" id="ba-dom" data-tip="DOM Pruning: Compact (14k)">
        <span class="pill pill-c">14k</span>
      </button>
      <button class="btn" id="ba-vram" data-tip="LM Studio: idle">
        ${CHIP_SVG}
      </button>
      <button class="btn" id="ba-routines" data-tip="Routines">
        ${BOLT_SVG}
      </button>
      <button class="btn" id="ba-settings" data-tip="Settings">
        ${GEAR_SVG}
      </button>
      <div class="divider"></div>
      <button class="btn btn-close" id="ba-close" data-tip="Вимкнути BroAnt">×</button>
    `;

    shadow.append(style, dock);
    document.documentElement.appendChild(host);

    const btnOpen = shadow.getElementById('ba-open') as HTMLElement;
    const btnMcp = shadow.getElementById('ba-mcp') as HTMLElement;
    const ledMcp = btnMcp.querySelector('.led-mcp') as HTMLElement;
    const btnAct = shadow.getElementById('ba-act') as HTMLElement;
    const ledAct = btnAct.querySelector('.led-act') as HTMLElement;
    const btnDom = shadow.getElementById('ba-dom') as HTMLElement;
    const pillDom = btnDom.querySelector('.pill-c') as HTMLElement;
    const btnVram = shadow.getElementById('ba-vram') as HTMLElement;
    const btnRoutines = shadow.getElementById('ba-routines') as HTMLElement;
    const btnSettings = shadow.getElementById('ba-settings') as HTMLElement;
    const btnClose = shadow.getElementById('ba-close') as HTMLElement;
    const tuckMcp = shadow.getElementById('ba-tuck-mcp') as HTMLElement;
    const tuckAct = shadow.getElementById('ba-tuck-act') as HTMLElement;

    let currentState: RailStateSnapshot = { ...DEFAULT_STATE };
    let isDragging = false;
    let dragStartY = 0;
    let initialTop = 14;
    let hasMoved = false;

    function formatActivityTooltip(activity: BridgeActivityState): string {
      const src = activity.source ?? (activity.activeTasks > 0 ? 'mcp' : activity.activeSessions > 0 ? 'local' : 'none');
      const srcLabel = src === 'both' ? 'MCP + LM Studio' : src === 'mcp' ? 'MCP (Antigravity)' : src === 'local' ? 'LM Studio' : 'None';
      if (activity.phase === 'executing') {
        return `Executing (${srcLabel}) • Tool: ${activity.currentTool ?? 'running'} • Click to STOP`;
      }
      if (activity.phase === 'thinking') {
        return `Thinking (${srcLabel}) • Click to STOP`;
      }
      if (activity.phase === 'held') {
        return `Session active (${srcLabel}) • Click to Detach`;
      }
      return `Agent Activity: Idle (${srcLabel})`;
    }

    function render(state: RailStateSnapshot) {
      currentState = state;
      const shouldHide = !state.visible || Boolean(state.sidePanelOpen);
      dock.classList.toggle('hidden', shouldHide);
      if (shouldHide) return;

      dock.dataset.theme = state.theme;
      dock.style.setProperty('--ba-dock-opacity', String(typeof state.opacity === 'number' ? state.opacity : 0.85));

      if (typeof state.topPx === 'number' && !isDragging) {
        host.style.top = `${state.topPx}px`;
      }

      // LED 1: MCP Gate
      let mcpState = 'off';
      let mcpTip = 'MCP Gate: Disabled';
      if (state.bridgeEnabled) {
        if (state.bridgeConnected) {
          mcpState = 'connected';
          mcpTip = 'MCP Gate: Connected (ready)';
        } else {
          mcpState = 'on';
          mcpTip = 'MCP Gate: Waiting for Bridge';
        }
      }
      ledMcp.dataset.state = mcpState;
      btnMcp.dataset.tip = mcpTip;
      tuckMcp.dataset.state = mcpState;

      // LED 2: Agent Activity (dual source)
      const phase = state.activity.phase;
      ledAct.dataset.state = phase;
      tuckAct.dataset.state = phase;
      btnAct.dataset.tip = formatActivityTooltip(state.activity);
      btnAct.dataset.active = String(phase !== 'idle');
      btnAct.dataset.executing = String(phase === 'executing');

      // DOM Pruning
      pillDom.textContent = state.pruningMode === 'compact' ? '14k' : 'Full';
      btnDom.dataset.tip = `DOM Pruning: ${state.pruningMode === 'compact' ? 'Compact (14k)' : 'Standard (full)'}`;

      // VRAM / Model
      btnVram.dataset.tip = state.vramLabel;
    }

    const sendAction = (action: string, payload?: Record<string, unknown>) => {
      chrome.runtime.sendMessage({ type: 'broant_rail_action', action, ...payload }).catch(() => undefined);
    };

    // Vertical Drag & Drop logic on dock (excluding button clicks)
    dock.addEventListener('pointerdown', (e: PointerEvent) => {
      if ((e.target as HTMLElement).closest('.btn') || dock.classList.contains('tucked')) {
        return;
      }
      isDragging = true;
      hasMoved = false;
      dragStartY = e.clientY;
      const currentTop = parseInt(host.style.top || '14', 10);
      initialTop = isNaN(currentTop) ? 14 : currentTop;
      dock.setPointerCapture(e.pointerId);
      dock.classList.add('dragging');
    });

    dock.addEventListener('pointermove', (e: PointerEvent) => {
      if (!isDragging) return;
      const deltaY = e.clientY - dragStartY;
      if (Math.abs(deltaY) > 3) {
        hasMoved = true;
      }
      const rawTop = initialTop + deltaY;
      const maxTop = Math.max(8, window.innerHeight - dock.offsetHeight - 8);
      const clampedTop = Math.min(Math.max(8, rawTop), maxTop);
      host.style.top = `${clampedTop}px`;
    });

    const endDrag = (e: PointerEvent) => {
      if (!isDragging) return;
      isDragging = false;
      dock.classList.remove('dragging');
      try {
        dock.releasePointerCapture(e.pointerId);
      } catch {}
      if (hasMoved) {
        const finalTop = parseInt(host.style.top || '14', 10);
        sendAction('save_rail_top', { topPx: finalTop });
      }
    };

    dock.addEventListener('pointerup', endDrag);
    dock.addEventListener('pointercancel', endDrag);

    dock.addEventListener('click', e => {
      if (dock.classList.contains('tucked')) {
        dock.classList.remove('tucked');
        e.stopPropagation();
      }
    });

    let clickTimer: number | null = null;
    btnOpen.addEventListener('click', e => {
      e.stopPropagation();
      if (clickTimer !== null) {
        window.clearTimeout(clickTimer);
        clickTimer = null;
        dock.classList.toggle('tucked');
      } else {
        clickTimer = window.setTimeout(() => {
          clickTimer = null;
          sendAction('open_sidepanel');
        }, 240);
      }
    });

    btnMcp.addEventListener('click', () => sendAction('toggle_mcp'));

    btnAct.addEventListener('click', () => {
      if (currentState.activity.phase !== 'idle') {
        sendAction('kill_all');
      }
    });

    btnDom.addEventListener('click', () => sendAction('toggle_pruning'));
    btnRoutines.addEventListener('click', () => sendAction('open_routines'));
    btnSettings.addEventListener('click', () => sendAction('open_options'));
    btnClose.addEventListener('click', (e) => {
      e.stopPropagation();
      sendAction('power_off');
    });

    // Port connection with hard unmount on rail_unmount
    let port: chrome.runtime.Port | null = null;
    let unmounted = false;
    function connectPort() {
      if (unmounted) return;
      try {
        port = chrome.runtime.connect({ name: 'broant-rail' });
        port.onMessage.addListener((msg: { type: string; state?: RailStateSnapshot }) => {
          if (msg.type === 'rail_unmount') {
            unmounted = true;
            host.remove();
            port?.disconnect();
            port = null;
            return;
          }
          if (msg.type === 'rail_state' && msg.state) {
            render(msg.state);
          }
        });
        port.onDisconnect.addListener(() => {
          port = null;
          if (!unmounted) {
            setTimeout(connectPort, 3000);
          }
        });
      } catch {
        // Extension context invalidated
      }
    }
    connectPort();
  },
});
